import pandas as pd

def net_sharpe_table(bars, lookbacks, half_spreads_bp):
    """Annualised Sharpe of the momentum rule, one row per lookback,
    one column per half spread, each rounded to 3 places."""
    table = {}
    for h in half_spreads_bp:
        column = []
        for lookback in lookbacks:
            targets = target_positions(momentum_signal(bars["close"], lookback), 10_000)
            costs = lambda q, p: trade_cost(q, p, half_spread_bp=h)
            equity = backtest(bars, targets, costs=costs)["equity"]
            daily = equity.diff().dropna() / 1_000_000
            column.append(round(sharpe(daily), 3))
        table[h] = column
    return pd.DataFrame(table, index=list(lookbacks))
